function reveal(lat,cy){return `<details class="class-answer"><summary data-lat="Prikaži rešenje" data-cyrl="Прикажи решење"></summary><div class="answer-lat">${lat}</div><div class="answer-cyrl">${cy}</div></details>`}
function plan(x){const [id,area,lt,ct,li,ci,lf,cf,lex,cex,lq,cq,la,ca,correct]=x,stages=[
 {label:P('Uvod i obnavljanje','Увод и обнављање'),duration:5,content:P(`<h2>Početni problem</h2><p>${li}</p><div class="class-formula">${lf}</div>`,`<h2>Почетни проблем</h2><p>${ci}</p><div class="class-formula">${cf}</div>`)},
 {label:P('Novo gradivo','Ново градиво'),duration:8,content:P(`<h2>Ključna ideja</h2><p>${li}</p><div class="class-formula">${lf}</div><p class="teacher-note">Tražite da učenici pravilo izgovore svojim rečima.</p>`,`<h2>Кључна идеја</h2><p>${ci}</p><div class="class-formula">${cf}</div><p class="teacher-note">Тражите да ученици правило изговоре својим речима.</p>`)},
 {label:P('Vođeni primeri','Вођени примери'),duration:10,content:P(`<h2>Rešavamo korak po korak</h2><ol class="class-tasks">${lex.map(e=>`<li>${e}</li>`).join('')}</ol>${reveal(`<b>Zaključak:</b> ${lf}`,`<b>Закључак:</b> ${cf}`)}`,`<h2>Решавамо корак по корак</h2><ol class="class-tasks">${cex.map(e=>`<li>${e}</li>`).join('')}</ol>${reveal(`<b>Zaključak:</b> ${lf}`,`<b>Закључак:</b> ${cf}`)}`)},
 {label:P('Rad na tabli','Рад на табли'),duration:8,content:P(`<h2>Dodirni tačan odgovor</h2><p>${lq}</p>`,`<h2>Додирни тачан одговор</h2><p>${cq}</p>`),activity:{type:'single',question:P(lq,cq),choices:P(la,ca),answer:correct,explanation:P(la[correct],ca[correct])}},
 {label:P('Samostalni rad','Самостални рад'),duration:10,content:P(`<h2>Uradi, pa proveri</h2><ol class="class-tasks">${lex.map((e,i)=>`<li>${i%2?lq:e}</li>`).join('')}</ol>${reveal(`${lex.join('<br>')}<br><b>${lq}</b> ${la[correct]}`,`${cex.join('<br>')}<br><b>${cq}</b> ${ca[correct]}`)}`,`<h2>Уради, па провери</h2><ol class="class-tasks">${cex.map((e,i)=>`<li>${i%2?cq:e}</li>`).join('')}</ol>${reveal(`${lex.join('<br>')}<br><b>${lq}</b> ${la[correct]}`,`${cex.join('<br>')}<br><b>${cq}</b> ${ca[correct]}`)}`)},
 {label:P('Izlazna kartica','Излазна картица'),duration:4,content:P(`<h2>Mini-provera</h2><p class="exit-question">${lq}</p>${reveal(la[correct],ca[correct])}`,`<h2>Мини-провера</h2><p class="exit-question">${cq}</p>${reveal(la[correct],ca[correct])}`)}
 ];return{area,title:P(lt,ct),goals:P([li,'primeni pravilo na tipičnom primeru','obrazloži odgovor'],[ci,'примени правило на типичном примеру','образложи одговор']),stages}}
const plans=window.MatematikONClassroomPlans||(window.MatematikONClassroomPlans={});items.forEach(x=>{if(!plans[x[0]])plans[x[0]]=plan(x)});
