if(decimalPlan){decimalPlan.stages[3].content=P('<h2>Dodirni tačan znak</h2><p>Uporedi: 6,307 □ 6,37.</p>','<h2>Додирни тачан знак</h2><p>Упореди: 6,307 □ 6,37.</p>');decimalPlan.stages[3].activity={type:'single',question:P('6,307 □ 6,37','6,307 □ 6,37'),choices:P(['<','>','='],['<','>','=']),answer:0,explanation:P('6,307 < 6,370.','6,307 < 6,370.')}}
const vectorPlan=plans.vektori;if(vectorPlan){vectorPlan.stages[0].content[0]+='<div class="class-formula"><span class="vector-symbol">AB</span>: A → B</div>';vectorPlan.stages[0].content[1]+='<div class="class-formula"><span class="vector-symbol">AB</span>: A → B</div>'}
